  // ---------- PCB measurements ----------
  "<b>Smart</b>: click a pad, track, hole or region for its size, then a second one for pitch and clearance. Shift+click: area": "<b>Умное</b>: щёлкните площадку, дорожку, отверстие или полигон, чтобы узнать размер, затем второй объект — шаг и зазор. Shift+щелчок: площадь",
  "<b>Point to point</b> (M): click two points. Snaps to corners, pad centres and track edges": "<b>Точка–точка</b> (M): щёлкните две точки. Привязка к углам, центрам площадок и краям дорожек",
  "<b>Clearance</b> (C): click two features for the edge-to-edge gap": "<b>Зазор</b> (C): щёлкните два объекта, чтобы получить зазор кромка–кромка",
  "<b>Polyline</b> (L): click points; Enter or double-click finishes, Backspace removes the last": "<b>Ломаная</b> (L): щёлкайте точки; Enter или двойной щелчок завершает, Backspace убирает последнюю",
  "<b>Area</b> (A): click corners, close on the first point or Enter. Shift+click a closed shape for its area": "<b>Площадь</b> (A): щёлкайте углы, замкните на первой точке или Enter. Shift+щелчок по замкнутой фигуре даёт её площадь",
